import { useMemo, useState } from 'react';
import { Button, ButtonGroup, Card, Stack, Text } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
const MONTHS = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date: Date, days: number): Date {
  const next = startOfDay(date);
  next.setDate(next.getDate() + days);
  return next;
}

function isSameDay(a: Date | null, b: Date | null): boolean {
  if (!a || !b) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const today = startOfDay(new Date());
  const [selected, setSelected] = useState<Date | null>(value ? startOfDay(value) : null);
  const current = value !== undefined ? (value ? startOfDay(value) : null) : selected;
  const [visible, setVisible] = useState<Date>(current ?? today);

  const cells = useMemo(() => {
    const year = visible.getFullYear();
    const month = visible.getMonth();
    const offset = (new Date(year, month, 1).getDay() + 6) % 7;
    const total = new Date(year, month + 1, 0).getDate();
    const result: (Date | null)[] = Array.from({ length: offset }, () => null);
    for (let day = 1; day <= total; day += 1) {
      result.push(new Date(year, month, day));
    }
    return result;
  }, [visible]);

  const select = (date: Date) => {
    const normalized = startOfDay(date);
    setSelected(normalized);
    setVisible(normalized);
    onChange(normalized);
  };

  const shiftMonth = (delta: number) => {
    setVisible((prev) => new Date(prev.getFullYear(), prev.getMonth() + delta, 1));
  };

  const quickOptions = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: addDays(today, -1) },
    { label: 'Неделя назад', date: addDays(today, -7) },
  ];

  return (
    <Card>
      <Stack direction="column" gap="md">
        <ButtonGroup>
          {quickOptions.map((option) => (
            <Button
              key={option.label}
              size="sm"
              variant={isSameDay(current, option.date) ? 'primary' : 'secondary'}
              onClick={() => select(option.date)}
            >
              {option.label}
            </Button>
          ))}
        </ButtonGroup>

        <Stack direction="row" align="center" justify="space-between" gap="sm">
          <Button size="sm" variant="ghost" aria-label="Предыдущий месяц" onClick={() => shiftMonth(-1)}>
            ‹
          </Button>
          <Text weight="medium">
            {MONTHS[visible.getMonth()]} {visible.getFullYear()}
          </Text>
          <Button size="sm" variant="ghost" aria-label="Следующий месяц" onClick={() => shiftMonth(1)}>
            ›
          </Button>
        </Stack>

        <div
          role="grid"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            gap: 'var(--jx-space-xs)',
          }}
        >
          {WEEKDAYS.map((weekday) => (
            <Text key={weekday} size="sm" tone="muted" align="center">
              {weekday}
            </Text>
          ))}

          {cells.map((date, index) =>
            date ? (
              <Button
                key={date.toISOString()}
                size="sm"
                fullWidth
                variant={
                  isSameDay(current, date)
                    ? 'primary'
                    : isSameDay(today, date)
                      ? 'secondary'
                      : 'ghost'
                }
                aria-pressed={isSameDay(current, date)}
                onClick={() => select(date)}
              >
                {date.getDate()}
              </Button>
            ) : (
              <span key={`empty-${index}`} aria-hidden="true" />
            ),
          )}
        </div>
      </Stack>
    </Card>
  );
}

